// GENERATED by scripts/sync-skill.mjs from prototype/pixelface.js. Edit the prototype, not this copy.
// FEATURE_DEPTH: per-feature parallax depth used for yaw shifts (prototype/render.js).
const FEATURE_DEPTH = { eyeL: 4, eyeR: 1.6, nose: 3, mouth: 3, browL: 4, browR: 1.6, ear: 2.4 };
// Hand-placed pixel face for the pixel-art render path (canvas). At sprite scale
// a vector face quantises into noise, so the same face PARAMETERS are redrawn as
// deliberate pixel clusters after palette quantisation (crisp, readable at 1x).

const EYES = { L: { x: -2.5, y: -14.5 }, R: { x: 10.5, y: -14.5 } };

/**
 * ctx: the low-res buffer context. m: DOMMatrix head-local -> buffer pixels.
 * P: face params. pal: palette (hex). yaw: -1..1. time: seconds.
 */
export function drawPixelFace(ctx, m, P, pal, yaw = 0, time = 0) {
  ctx.save();
  ctx.setTransform(1, 0, 0, 1, 0, 0);
  const flip = m.a < 0 ? -1 : 1;
  const px = (x, y, w = 1, h = 1, c = pal.line) => {
    ctx.fillStyle = c;
    ctx.fillRect(Math.round(x), Math.round(y), w, h);
  };
  const at = (x, y) => m.transformPoint(new DOMPoint(x, y));
  for (const side of ['L', 'R']) {
    const e = EYES[side];
    const c = at(e.x + yaw * FEATURE_DEPTH[`eye${side}`], e.y);
    const outer = (side === 'R' ? 1 : -1) * flip;
    const ex = Math.round(c.x);
    const ey = Math.round(c.y);
    const narrow = side === 'L' && yaw > 0.4;
    const w = narrow ? 1 : 2;
    const x0 = outer > 0 ? ex - 1 : ex - w + 1;
    const open = P[`eyeOpen${side}`];
    const smile = P[`eyeSmile${side}`];
    const eff = open * (1 - smile * 0.6);
    const ang = P[`browAngle${side}`]; // + = angry (inner end down), - = worried
    const inner = -outer;
    if (P.eyeShut > 0.5) {
      // > < squeeze
      px(ex - inner, ey - 1);
      px(ex, ey);
      px(ex - inner, ey + 1);
    } else if (smile > 0.45 || (eff < 0.14 && smile > 0.3)) {
      // ^ happy arc
      px(ex - 1, ey + 1);
      px(ex, ey);
      px(ex + 1, ey + 1);
    } else if (eff < 0.14) {
      px(ex - 1, ey, 3, 1);
    } else {
      const h = Math.max(2, Math.min(4, Math.round(Math.min(eff, 1.3) * 3.2)));
      const top = ey + 2 - h;
      if (P.pupilSize < 0.7) {
        // shocked: white eye, tiny pupil
        px(x0, top, w + 1, h + 1, '#ffffff');
        px(x0 + (w > 1 ? 1 : 0), top + Math.floor(h / 2), 1, 1, pal.line);
      } else {
        px(x0, top, w, h, pal.irisDark);
        if (h >= 3) px(x0, top + Math.ceil(h / 2), w, Math.floor(h / 2), pal.iris);
        px(x0 + (P.pupilX * flip > 0.3 ? w - 1 : 0), top, 1, 1, '#ffffff');
      }
      // upper lash; its slope carries the brow (pixel brows vanish into the bangs)
      px(outer > 0 ? x0 : x0 - 1, top - 1, w + 1, 1, pal.line);
      if (ang > 0.25) {
        px(ex + inner, top, 1, 1, pal.line); // inner corner pulled down
        px(ex + inner, top - 2, 1, 1, pal.line);
        if (ang > 0.6) px(ex + inner * 2, top - 1, 1, 1, pal.line);
      } else if (ang < -0.25) {
        px(ex + outer, top, 1, 1, pal.line); // outer corner droops
        px(ex + inner, top - 2, 1, 1, pal.line); // worried brow lifts at the inner end
      }
    }
    if (P.blush > 0.3) px(ex - 1, ey + 3, 2, 1, pal.blush);
    if (P.tears > 0.2) px(ex, ey + 2, 1, Math.max(1, Math.round(P.tears * 4)), '#7cc8ff');
  }
  // mouth
  const mc = at(6.5 + yaw * FEATURE_DEPTH.mouth, -5.2);
  const mx = Math.round(mc.x);
  const my = Math.round(mc.y);
  const half = Math.max(1, Math.round(P.mouthWidth * 1.2));
  if (P.mouthOpen > 0.12) {
    const h = Math.max(1, Math.round(P.mouthOpen * 3));
    px(mx - half, my, half * 2, h, pal.mouth);
    if (P.mouthCurve > 0.4 && h >= 2) px(mx - half, my, half * 2, 1, '#ffffff');
    else if (h >= 2) px(mx - half + 1, my + h - 1, Math.max(1, half * 2 - 2), 1, pal.tongue);
  } else {
    const curve = P.mouthCurve;
    const smirk = P.mouthSmirk * flip;
    const lift = curve > 0.3 ? -1 : curve < -0.3 ? 1 : 0;
    px(mx - half + 1, my, Math.max(1, half * 2 - 2), 1, pal.line);
    px(mx - half, my + lift + (smirk < -0.3 ? -1 : 0), 1, 1, pal.line);
    px(mx + half - 1, my + lift + (smirk > 0.3 ? -1 : 0), 1, 1, pal.line);
  }
  // effects near the head
  const top = at(15, -36);
  if (P.angerMark > 0.3) {
    const tx = Math.round(top.x);
    const ty = Math.round(top.y);
    px(tx - 1, ty, 3, 1, '#e8283a');
    px(tx, ty - 1, 1, 3, '#e8283a');
  }
  if (P.sweat > 0.3) {
    const s = at(22, -30);
    const bob = Math.round(Math.sin(time * 6));
    px(s.x, s.y - 1 + bob, 1, 1, '#bfe6ff');
    px(s.x - 1, s.y + bob, 3, 2, '#bfe6ff');
  }
  if (P.sparkle > 0.4 && Math.floor(time * 8) % 2 === 0) {
    const s = at(25, -38);
    px(s.x, s.y - 1, 1, 3, '#ffffff');
    px(s.x - 1, s.y, 3, 1, '#ffffff');
  }
  if (P.gloom > 0.3) {
    for (let i = 0; i < 3; i++) {
      const g = at(1 + i * 4, -33);
      px(g.x, g.y, 1, 3, '#6a5acd');
    }
  }
  ctx.restore();
}
